// LCD 1602 I2C — harorat va sanoqni ko'rsatish
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);   // manzil ishlamasa 0x3F ni sinang

int sanoq = 0;

void setup() {
  lcd.init();
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print("Tarbion maktabi");
  delay(1500);
  lcd.clear();
}

void loop() {
  lcd.setCursor(0, 0);
  lcd.print("Sanoq:");

  lcd.setCursor(0, 1);
  lcd.print(sanoq);
  lcd.print("    ");        // eski raqam qoldig'ini o'chirish

  sanoq++;
  delay(500);
}

